.lantern-core{position: relative; overflow: hidden; border-radius: 999px; background: linear-gradient(rgba(20, 22, 24, 0.94), rgba(11, 13, 16, 0.9)); border: 1px solid rgba(255, 255, 255, 0.12); color: white; transition: transform 0.45s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.45s, border-color 0.35s; box-shadow: rgba(255, 255, 255, 0.06) 0px 1px 0px inset, rgba(0, 0, 0, 0.28) 0px 18px 60px;}
.lantern-core::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(circle, rgba(255, 189, 98, 0.14), transparent 36%), radial-gradient(circle, rgba(255, 145, 62, 0.08), transparent 54%); opacity: 0; transition: 0.45s; pointer-events: none;}
.lantern-core::after{content: ""; position: absolute; inset: -120%; background: linear-gradient(120deg, transparent 44%, rgba(255, 193, 103, 0.52) 50%, transparent 56%); transform: translateX(-140%) rotate(10deg); animation: 9s ease-in-out 0s infinite normal none running sheen; pointer-events: none; mix-blend-mode: screen;}
.lantern-core:hover{transform: translateY(-3px); box-shadow: rgba(255, 255, 255, 0.06) 0px 1px 0px inset, rgba(255, 189, 98, 0.18) 0px 0px 0px 1px, rgba(0, 0, 0, 0.34) 0px 22px 60px;}
.lantern-core:hover::before{opacity: 1;}
.hero{min-height: 100svh; position: relative; overflow: hidden; background: linear-gradient(rgba(255, 153, 84, 0.3) 0%, rgba(18, 21, 28, 0.86) 52%, rgba(11, 14, 18, 0.95) 100%);}
.hero-video{position: absolute; inset: 0px; width: 100%; height: 100%; object-fit: cover; will-change: transform; mask-image: radial-gradient(circle, black 0px, black 52%, rgba(0, 0, 0, 0.92) 64%, rgba(0, 0, 0, 0.62) 78%, transparent 94%);}
.hero::after{content: ""; position: absolute; inset: 0px; background: radial-gradient(circle, rgba(255, 189, 98, 0.14), transparent 18%), radial-gradient(circle, rgba(0, 0, 0, 0.15), rgba(0, 0, 0, 0.22) 55%, rgba(0, 0, 0, 0.38) 100%); pointer-events: none;}
.hero-center{position: relative; z-index: 5; min-height: 100svh; display: flex; align-items: center; justify-content: center; text-align: center; padding: 110px 24px 42px;}
.hero-shell{max-width: 980px; padding: 28px 30px 30px; border-radius: 2.2rem;}
.hero-kicker{display: inline-flex; align-items: center; gap: 10px; padding: 12px 16px; border-radius: 999px; background: rgba(255, 255, 255, 0.08); border: 1px solid rgba(255, 255, 255, 0.12); color: rgba(255, 255, 255, 0.8); text-transform: uppercase; letter-spacing: 0.3em; font-size: 10px;}
.hero-kicker span{width: 8px; height: 8px; background: var(--amber); display: inline-block; box-shadow: rgba(255, 193, 103, 0.55) 0px 0px 18px;}
.hero-title{margin-top: 24px; font-size: clamp(4.4rem, 10vw, 9.2rem); line-height: 0.82; letter-spacing: -0.09em; color: white; text-shadow: rgba(0, 0, 0, 0.22) 0px 18px 38px; animation: 7s ease-in-out 0s infinite normal none running breath;}
.hero-sub{margin: 26px auto 0px; max-width: 760px; font-size: 18px; line-height: 1.95; color: rgba(255, 255, 255, 0.84);}
.hero-actions{display: flex; flex-wrap: wrap; justify-content: center; gap: 14px; margin-top: 34px;}
.hero-actions button{height: 56px; padding: 0px 22px; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; cursor: pointer; font-size: 10px; letter-spacing: 0.26em; text-transform: uppercase;}
.hero-chips{display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-top: 24px;}
.hero-chips span{padding: 10px 12px; border-radius: 999px; background: rgba(255, 255, 255, 0.09); border: 1px solid rgba(255, 255, 255, 0.09); color: rgba(255, 255, 255, 0.9); text-transform: uppercase; letter-spacing: 0.2em; font-size: 10px;}
.reveal{opacity: 0; transform: translateY(30px); transition: opacity 0.8s, transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);}
.reveal.in{opacity: 1; transform: translateY(0px);}
@media (max-width: 760px){.hero-shell{padding: 18px 14px 20px;}}
@media (max-width: 760px){.hero-title{font-size: clamp(3.4rem, 14vw, 6.8rem);}}
@media (max-width: 760px){.hero-sub{font-size: 15px;}}
