.display{font-family: "Cormorant Garamond", serif; letter-spacing: -0.06em;}
.mono{font-family: "IBM Plex Mono", monospace;}
.section{padding: 124px 0px;}
.wrap{width: min(1600px, 100% - 32px); margin: 0px auto;}
.section-heading{display: flex; justify-content: space-between; gap: 22px; align-items: flex-end; margin-bottom: 30px;}
.section-heading h2{font-size: clamp(3rem, 6vw, 6.2rem); line-height: 0.9; letter-spacing: -0.07em;}
.section-heading p{max-width: 470px; color: rgba(255, 255, 255, 0.7); line-height: 1.9;}
.code-window{position: relative; width: min(1080px, 100% - 32px); margin: 0px auto; border-radius: 2.6rem; overflow: hidden; background: linear-gradient(rgba(22, 38, 40, 0.9), rgba(10, 16, 18, 0.92)); border: 1px solid rgba(255, 255, 255, 0.08); box-shadow: rgba(0, 0, 0, 0.38) 0px 26px 80px;}
.code-top{display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 18px 20px; border-bottom: 1px solid rgba(255, 255, 255, 0.08); background: rgba(255, 255, 255, 0.03);}
.dots{display: flex; gap: 8px;}
.dots span{width: 10px; height: 10px; border-radius: 999px; background: rgba(255, 255, 255, 0.16);}
.code-top .tag{text-transform: uppercase; letter-spacing: 0.28em; font-size: 10px; color: rgba(255, 255, 255, 0.62);}
.code-body{padding: 34px 22px 28px; display: grid; grid-template-columns: 1fr 0.72fr; gap: 28px;}
.manifesto{min-height: 320px; padding: 24px; border-radius: 2rem; background: rgba(255, 255, 255, 0.04); border: 1px solid rgba(255, 255, 255, 0.08); position: relative; overflow: hidden;}
.manifesto::before{content: ""; position: absolute; inset: 0px; background: linear-gradient(rgba(255, 255, 255, 0.04), transparent 24%), repeating-linear-gradient(rgba(255, 255, 255, 0.04) 0px, rgba(255, 255, 255, 0.04) 1px, transparent 1px, transparent 28px); opacity: 0.24; pointer-events: none;}
.manifesto .cursor{display: inline-block; width: 1px; height: 1.2em; background: rgba(255, 205, 127, 0.95); margin-left: 2px; animation: 1s steps(2) 0s infinite normal none running blink; vertical-align: -3px;}
.manifesto pre{margin: 0px; white-space: pre-wrap; word-break: break-word; font-family: "IBM Plex Mono", monospace; font-size: 12px; line-height: 1.9; color: rgba(255, 255, 255, 0.8);}
.manifesto .headline{margin-bottom: 16px; text-transform: uppercase; letter-spacing: 0.28em; color: rgba(255, 255, 255, 0.58); font-size: 10px;}
.metrics{display: flex; flex-direction: column; gap: 16px;}
.metric{padding: 20px; border-radius: 1.8rem; background: rgba(255, 255, 255, 0.05); border: 1px solid rgba(255, 255, 255, 0.08);}
.metric .label{text-transform: uppercase; letter-spacing: 0.28em; font-size: 10px; color: rgba(255, 255, 255, 0.58);}
.metric .value{margin-top: 10px; font-size: clamp(2rem, 4vw, 3.4rem); line-height: 1; letter-spacing: -0.06em; color: white;}
.metric .sub{margin-top: 10px; font-size: 14px; line-height: 1.8; color: rgba(255, 255, 255, 0.72);}
.reveal{opacity: 0; transform: translateY(30px); transition: opacity 0.8s, transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);}
.reveal.in{opacity: 1; transform: translateY(0px);}
